     5→
     6→const corsHeaders = {
     7→  "Access-Control-Allow-Origin": "*",
     8→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
     9→};
    10→
    11→Deno.serve(async (req) => {
    12→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
    13→
    14→  try {
    15→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    16→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
    17→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    18→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    19→
    20→    if (!DODO_API_KEY) {
    21→      return new Response(JSON.stringify({ error: "Dodo Payments not configured" }), {
    22→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    23→      });
    24→    }
    25→
    26→    const authHeader = req.headers.get("Authorization");
    27→    if (!authHeader) {
    28→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
    29→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
    30→      });
    31→    }
    32→
    33→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    34→      global: { headers: { Authorization: authHeader } },
    35→    });
    36→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    37→    if (userError || !user) {
    38→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
    39→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
    40→      });
    41→    }
    42→
    43→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    44→
    45→    // Get user's dodo subscription ID
    46→    const { data: profile } = await supabase
    47→      .from("profiles")
    48→      .select("dodo_subscription_id")
    49→      .eq("user_id", user.id)
    50→      .single();
    51→
    52→    if (!profile?.dodo_subscription_id) {
    53→      return new Response(JSON.stringify({ error: "No active Dodo subscription found" }), {
    54→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
    55→      });
    56→    }
    57→
    58→    // Cancel at period end via Dodo SDK (recommended)
    59→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
    60→    const isLive = DODO_ENV === "live_mode";
    61→    const dodo = new DodoPayments({
    62→      bearerToken: DODO_API_KEY!,
    63→      baseURL: isLive
    64→        ? "https://live.dodopayments.com"
    65→        : "https://test.dodopayments.com",
    66→    });
    67→
    68→    await dodo.subscriptions.update(profile.dodo_subscription_id, {
    69→      cancel_at_next_billing_date: true,
    70→    });
    71→
    72→    // Update profile — subscription will remain active until end of period
    73→    // The webhook will handle the final downgrade
    74→
    75→    return new Response(JSON.stringify({ success: true, message: "Subscription will cancel at end of billing period" }), {
    76→      headers: { ...corsHeaders, "Content-Type": "application/json" },
    77→    });
    78→  } catch (err: unknown) {
    79→    console.error("cancel-dodo-subscription error:", err);
    80→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
    81→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    82→    });
    83→  }
    84→});
