import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Loader2, CheckCircle, AlertCircle, Wallet, Coins, RefreshCw, Copy } from "lucide-react";

const WalletSettingsTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);
  const [savingCost, setSavingCost] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [verifying, setVerifying] = useState(false);
  const [minAmount, setMinAmount] = useState<string>("");
  const [perCost, setPerCost] = useState<string>("");

  const { data: config, isLoading } = useQuery({
    queryKey: ["platform_config_wallet"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("payg_per_resume_cost, topup_min_amount, topup_dodo_product_id")
        .limit(1)
        .single();
      if (error) throw error;
      return data as any;
    },
    refetchOnWindowFocus: false,
  });

  const effectiveMin = minAmount || String(config?.topup_min_amount ?? "1");
  const effectiveCost = perCost || String(config?.payg_per_resume_cost ?? "0.07");
  const perResumeCost = parseFloat(effectiveCost) || 0.07;
  const previewAmount = 5;
  const previewCredits = perResumeCost > 0 ? Math.floor(previewAmount / perResumeCost) : 0;

  const handleSaveMin = async () => {
    const val = parseFloat(effectiveMin);
    if (isNaN(val) || val < 0.5) {
      toast.error("Minimum amount must be at least $0.50");
      return;
    }
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({ topup_min_amount: val } as any)
        .not("id", "is", null);
      if (error) throw error;

      // If linked to Dodo, update PWYW min price too
      if (config?.topup_dodo_product_id) {
        await supabase.functions.invoke("manage-dodo-product", {
          body: {
            action: "update",
            product_id: config.topup_dodo_product_id,
            type: "pack",
            price: val,
            pay_what_you_want: true,
            pwyw_min_price: val,
          },
        });
      }

      toast.success("Minimum top-up amount saved");
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      qc.invalidateQueries({ queryKey: ["platform_config"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleSaveCost = async () => {
    const val = parseFloat(effectiveCost);
    if (isNaN(val) || val <= 0) {
      toast.error("Per-resume cost must be greater than $0");
      return;
    }
    setSavingCost(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({ payg_per_resume_cost: val } as any)
        .not("id", "is", null);
      if (error) throw error;
      toast.success("Per-resume cost saved");
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      qc.invalidateQueries({ queryKey: ["platform_config"] });
      qc.invalidateQueries({ queryKey: ["platform_config_topup"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setSavingCost(false);
    }
  };

  const handleSyncToDodo = async () => {
    const minVal = parseFloat(effectiveMin) || 1;
    setSyncing(true);
    try {
      const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
        body: {
          action: "create",
          type: "pack",
          name: "Wallet Top-Up",
          price: minVal,
          credits: 0,
          description: "Custom wallet recharge — credits calculated at checkout based on amount paid.",
          pay_what_you_want: true,
          pwyw_min_price: minVal,
          pwyw_max_price: 1000,
        },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);

      const productId = data?.product_id;
      if (!productId) throw new Error("No product ID returned from Dodo");

      const { error: updateError } = await supabase
        .from("platform_config")
        .update({ topup_dodo_product_id: productId } as any)
        .not("id", "is", null);
      if (updateError) throw updateError;

      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });

      // Auto-verify PWYW status after creation
      const verifyResp = await supabase.functions.invoke("manage-dodo-product", {
        body: { action: "verify", product_id: productId },
      });
      const verifyData = verifyResp.data;
      const pwyw = verifyData?.product?.price?.pay_what_you_want;
      if (pwyw) {
        toast.success("Wallet Top-Up product created & PWYW verified ✓");
      } else {
        toast.warning(`Product ${productId} was created, but Dodo still shows PWYW as off. Enable 'Pay What You Want' for this product in the Dodo dashboard, then click Verify.`);
      }
    } catch (err: any) {
      toast.error("Failed to sync: " + (err.message || "Unknown error"));
    } finally {
      setSyncing(false);
    }
  };

  const handleVerify = async () => {
    if (!config?.topup_dodo_product_id) return;
    setVerifying(true);
    try {
      const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
        body: { action: "verify", product_id: config.topup_dodo_product_id },
      });
      if (error) throw error;
      if (data?.exists) {
        const product = data?.product;
        const pwyw = product?.pay_what_you_want;
        if (pwyw) {
          toast.success(`Product verified ✓ — PWYW enabled (min: $${(product?.price?.pay_what_you_want_min_price ?? 0) / 100})`);
        } else {
          toast.warning("Product exists but PWYW is NOT enabled. Click 'Recreate on Dodo' to fix.");
        }
      } else {
        await supabase
          .from("platform_config")
          .update({ topup_dodo_product_id: null } as any)
          .not("id", "is", null);
        qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
        toast.error("Product not found on Dodo — link cleared. Click 'Create on Dodo' to recreate.");
      }
    } catch (err: any) {
      toast.error("Verify failed: " + (err.message || "Unknown error"));
    } finally {
      setVerifying(false);
    }
  };

  const handleRecreate = async () => {
    // Clear existing link, then create new
    await supabase
      .from("platform_config")
      .update({ topup_dodo_product_id: null } as any)
      .not("id", "is", null);
    qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
    await handleSyncToDodo();
  };

  const handleCopyProductId = async (productId: string) => {
    await navigator.clipboard.writeText(productId);
    toast.success("Product ID copied");
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-sm flex items-center gap-2">
            <Wallet className="h-4 w-4 text-primary" />
            Wallet Top-Up Configuration
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Per-resume cost (editable) */}
          <div className="flex items-center gap-3">
            <div className="flex-1">
              <p className="text-sm font-medium mb-1">Per-Resume Cost (USD)</p>
              <p className="text-xs text-muted-foreground mb-1.5">
                How much each credit costs. Used to calculate credits from dollar amounts.
              </p>
              <div className="flex gap-2">
                <div className="relative max-w-[120px]">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                  <Input
                    type="number"
                    step="0.01"
                    min="0.01"
                    className="pl-7 text-sm"
                    value={perCost || String(config?.payg_per_resume_cost ?? 0.07)}
                    onChange={(e) => setPerCost(e.target.value)}
                  />
                </div>
                <Button size="sm" onClick={handleSaveCost} disabled={savingCost}>
                  {savingCost ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}
                  Save
                </Button>
              </div>
            </div>
          </div>

          {/* Minimum top-up amount */}
          <div className="flex items-center gap-3">
            <div className="flex-1">
              <p className="text-sm font-medium mb-1">Minimum Top-Up Amount (USD)</p>
              <div className="flex gap-2">
                <div className="relative max-w-[120px]">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                  <Input
                    type="number"
                    step="0.5"
                    min="0.5"
                    className="pl-7 text-sm"
                    value={minAmount || String(config?.topup_min_amount ?? 1)}
                    onChange={(e) => setMinAmount(e.target.value)}
                  />
                </div>
                <Button size="sm" onClick={handleSaveMin} disabled={saving}>
                  {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}
                  Save
                </Button>
              </div>
              <p className="text-[11px] text-muted-foreground mt-1">
                Also syncs to Dodo PWYW minimum if product is linked.
              </p>
            </div>
          </div>

          {/* Preview */}
          <div className="rounded-lg bg-accent/50 border border-border p-3">
            <p className="text-xs font-medium text-muted-foreground mb-1">Preview</p>
            <div className="flex items-center gap-2 text-sm">
              <span>User pays</span>
              <Badge variant="outline">${previewAmount}</Badge>
              <span>→ gets</span>
              <Badge className="gap-1">
                <Coins className="h-3 w-3" />
                {previewCredits} credits
              </Badge>
            </div>
            <p className="text-[11px] text-muted-foreground mt-1">
              Formula: floor(amount / ${perResumeCost}) = credits
            </p>
          </div>

          {/* Dodo Product Link */}
          <div className="border-t pt-3">
            <p className="text-sm font-medium mb-2">Dodo Payment Product (PWYW)</p>
            {config?.topup_dodo_product_id ? (
              <div className="space-y-2">
                <div className="flex items-center gap-2 flex-wrap">
                  <Badge variant="secondary" className="gap-1 text-xs">
                    <CheckCircle className="h-3 w-3 text-emerald-600" />
                    {config.topup_dodo_product_id}
                  </Badge>
                  <Button variant="outline" size="sm" onClick={() => handleCopyProductId(config.topup_dodo_product_id)}>
                    <Copy className="h-3.5 w-3.5 mr-1" />
                    Copy ID
                  </Button>
                  <Button variant="outline" size="sm" onClick={handleVerify} disabled={verifying}>
                    {verifying ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <RefreshCw className="h-3.5 w-3.5 mr-1" />}
                    Verify
                  </Button>
                  <Button variant="outline" size="sm" onClick={handleRecreate} disabled={syncing}>
                    {syncing ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}
                    Recreate on Dodo
                  </Button>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <Badge variant="outline" className="gap-1 text-xs text-amber-600">
                  <AlertCircle className="h-3 w-3" />
                  Not linked
                </Badge>
                <Button size="sm" onClick={handleSyncToDodo} disabled={syncing}>
                  {syncing ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}
                  Create on Dodo
                </Button>
              </div>
            )}
            <p className="text-[11px] text-muted-foreground mt-1">
              Dodo currently uses this linked product for all wallet top-ups. If Verify shows PWYW off, enable "Pay What You Want" in Dodo for this product, then checkout will accept any amount above your minimum.
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default WalletSettingsTab;

