import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Loader2, CheckCircle, AlertCircle, Wallet, Coins,
  RefreshCw, Copy, ExternalLink, Link2, XCircle, ShieldCheck,
} from "lucide-react";

interface VerifyResult {
  exists: boolean;
  is_active?: boolean;
  dodo_name?: string;
  dodo_price?: {
    price?: number;
    type?: string;
    pay_what_you_want?: boolean;
    pay_what_you_want_min_price?: number;
    pay_what_you_want_max_price?: number;
  };
  product?: any;
  error?: string;
}

const WalletSettingsTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);
  const [savingCost, setSavingCost] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [verifying, setVerifying] = useState(false);
  const [minAmount, setMinAmount] = useState<string>("");
  const [perCost, setPerCost] = useState<string>("");
  const [manualProductId, setManualProductId] = useState<string>("");
  const [linking, setLinking] = useState(false);
  const [verifyResult, setVerifyResult] = useState<VerifyResult | null>(null);

  const { data: config, isLoading } = useQuery({
    queryKey: ["platform_config_wallet"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("payg_per_resume_cost, topup_min_amount, topup_dodo_product_id")
        .limit(1)
        .single();
      if (error) throw error;
      return data as any;
    },
    refetchOnWindowFocus: false,
  });

  const effectiveMin = minAmount || String(config?.topup_min_amount ?? "1");
  const effectiveCost = perCost || String(config?.payg_per_resume_cost ?? "0.07");
  const perResumeCost = parseFloat(effectiveCost) || 0.07;
  const previewAmount = 5;
  const previewCredits = perResumeCost > 0 ? Math.floor(previewAmount / perResumeCost) : 0;

  const handleSaveMin = async () => {
    const val = parseFloat(effectiveMin);
    if (isNaN(val) || val < 0.5) { toast.error("Minimum amount must be at least $0.50"); return; }
    setSaving(true);
    try {
      const { error } = await supabase.from("platform_config").update({ topup_min_amount: val } as any).not("id", "is", null);
      if (error) throw error;
      if (config?.topup_dodo_product_id) {
        await supabase.functions.invoke("manage-dodo-product", {
          body: { action: "update", product_id: config.topup_dodo_product_id, type: "pack", price: val, pay_what_you_want: true, pwyw_min_price: val },
        });
      }
      toast.success("Minimum top-up amount saved");
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      qc.invalidateQueries({ queryKey: ["platform_config"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally { setSaving(false); }
  };

  const handleSaveCost = async () => {
    const val = parseFloat(effectiveCost);
    if (isNaN(val) || val <= 0) { toast.error("Per-resume cost must be greater than $0"); return; }
    setSavingCost(true);
    try {
      const { error } = await supabase.from("platform_config").update({ payg_per_resume_cost: val } as any).not("id", "is", null);
      if (error) throw error;
      toast.success("Per-resume cost saved");
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      qc.invalidateQueries({ queryKey: ["platform_config"] });
      qc.invalidateQueries({ queryKey: ["platform_config_topup"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally { setSavingCost(false); }
  };

  const runVerify = async (productId: string): Promise<VerifyResult> => {
    const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
      body: { action: "verify", product_id: productId },
    });
    if (error) throw error;
    return data as VerifyResult;
  };

  const handleVerify = async () => {
    if (!config?.topup_dodo_product_id) return;
    setVerifying(true);
    setVerifyResult(null);
    try {
      const result = await runVerify(config.topup_dodo_product_id);
      setVerifyResult(result);
      if (!result.exists) {
        await supabase.from("platform_config").update({ topup_dodo_product_id: null } as any).not("id", "is", null);
        qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
        toast.error("Product not found on Dodo — link cleared");
      }
    } catch (err: any) {
      setVerifyResult({ exists: false, error: err.message || "Verification failed" });
      toast.error("Verify failed: " + (err.message || "Unknown error"));
    } finally { setVerifying(false); }
  };

  const handleLinkManual = async () => {
    const pid = manualProductId.trim();
    if (!pid) { toast.error("Enter a product ID first"); return; }
    setLinking(true);
    setVerifyResult(null);
    try {
      const result = await runVerify(pid);
      setVerifyResult(result);
      if (!result.exists) {
        toast.error("Product not found on Dodo — check the ID and try again");
        return;
      }
      const { error } = await supabase.from("platform_config").update({ topup_dodo_product_id: pid } as any).not("id", "is", null);
      if (error) throw error;
      setManualProductId("");
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      toast.success("Product linked successfully ✓");
    } catch (err: any) {
      toast.error(err.message || "Failed to link");
    } finally { setLinking(false); }
  };

  const handleSyncToDodo = async () => {
    const minVal = parseFloat(effectiveMin) || 1;
    setSyncing(true);
    setVerifyResult(null);
    try {
      const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
        body: { action: "create", type: "pack", name: "Wallet Top-Up", price: minVal, credits: 0, description: "Custom wallet recharge — credits calculated at checkout based on amount paid.", pay_what_you_want: true, pwyw_min_price: minVal, pwyw_max_price: 1000 },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      const productId = data?.product_id;
      if (!productId) throw new Error("No product ID returned from Dodo");
      const { error: updateError } = await supabase.from("platform_config").update({ topup_dodo_product_id: productId } as any).not("id", "is", null);
      if (updateError) throw updateError;
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      const result = await runVerify(productId);
      setVerifyResult(result);
      toast.success("Wallet Top-Up product created on Dodo ✓");
    } catch (err: any) {
      toast.error("Failed to sync: " + (err.message || "Unknown error"));
    } finally { setSyncing(false); }
  };

  const handleRecreate = async () => {
    await supabase.from("platform_config").update({ topup_dodo_product_id: null } as any).not("id", "is", null);
    qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
    setVerifyResult(null);
    await handleSyncToDodo();
  };

  const handleUnlink = async () => {
    await supabase.from("platform_config").update({ topup_dodo_product_id: null } as any).not("id", "is", null);
    qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
    setVerifyResult(null);
    toast.success("Product unlinked");
  };

  const handleCopy = async (text: string) => {
    await navigator.clipboard.writeText(text);
    toast.success("Copied");
  };

  if (isLoading) {
    return <div className="flex items-center justify-center py-8"><Loader2 className="h-5 w-5 animate-spin text-muted-foreground" /></div>;
  }

  const linkedProductId = config?.topup_dodo_product_id as string | null;

  // Build product detail card from verify result
  const productCard = verifyResult?.exists ? (() => {
    const p = verifyResult.product || {};
    const priceObj = verifyResult.dodo_price || p.price || {};
    const priceUsd = (priceObj.price ?? 0) / 100;
    const priceType = priceObj.type === "recurring_price" ? "Recurring" : "One-time";
    const pwyw = priceObj.pay_what_you_want ?? p.pay_what_you_want ?? false;
    const pwywMin = pwyw ? (priceObj.pay_what_you_want_min_price ?? 0) / 100 : null;
    const isActive = verifyResult.is_active ?? true;
    const name = verifyResult.dodo_name || p.name || "Unknown";
    return { name, priceUsd, priceType, pwyw, pwywMin, isActive };
  })() : null;

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-sm flex items-center gap-2">
            <Wallet className="h-4 w-4 text-primary" />
            Wallet Top-Up Configuration
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-5">

          {/* Per-resume cost */}
          <div>
            <p className="text-sm font-medium mb-1">Per-Resume Cost (USD)</p>
            <p className="text-xs text-muted-foreground mb-2">How much each credit costs. Used to calculate credits from the dollar amount paid.</p>
            <div className="flex gap-2">
              <div className="relative max-w-[130px]">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                <Input type="number" step="0.01" min="0.01" className="pl-7 text-sm" value={perCost || String(config?.payg_per_resume_cost ?? 0.07)} onChange={(e) => setPerCost(e.target.value)} />
              </div>
              <Button size="sm" onClick={handleSaveCost} disabled={savingCost}>
                {savingCost ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}Save
              </Button>
            </div>
          </div>

          {/* Minimum top-up */}
          <div>
            <p className="text-sm font-medium mb-1">Minimum Top-Up Amount (USD)</p>
            <div className="flex gap-2">
              <div className="relative max-w-[130px]">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                <Input type="number" step="0.5" min="0.5" className="pl-7 text-sm" value={minAmount || String(config?.topup_min_amount ?? 1)} onChange={(e) => setMinAmount(e.target.value)} />
              </div>
              <Button size="sm" onClick={handleSaveMin} disabled={saving}>
                {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}Save
              </Button>
            </div>
            <p className="text-[11px] text-muted-foreground mt-1">Also syncs to Dodo PWYW minimum if product is linked.</p>
          </div>

          {/* Credit preview */}
          <div className="rounded-lg bg-accent/40 border border-border p-3">
            <p className="text-xs font-medium text-muted-foreground mb-1.5">Credit Preview</p>
            <div className="flex items-center gap-2 text-sm">
              <span className="text-muted-foreground">User pays</span>
              <Badge variant="outline">${previewAmount}</Badge>
              <span className="text-muted-foreground">→</span>
              <Badge className="gap-1 bg-primary/10 text-primary border-primary/20">
                <Coins className="h-3 w-3" />{previewCredits} credits
              </Badge>
            </div>
            <p className="text-[11px] text-muted-foreground mt-1">Formula: floor({previewAmount} ÷ {perResumeCost}) = {previewCredits}</p>
          </div>

          {/* Dodo product section */}
          <div className="border-t pt-4 space-y-3">
            <p className="text-sm font-medium">Dodo Payment Product (PWYW)</p>

            {linkedProductId ? (
              <div className="space-y-3">
                {/* Product ID row */}
                <div className="flex items-center gap-2 flex-wrap">
                  <code className="text-xs bg-muted px-2 py-1 rounded font-mono text-muted-foreground">{linkedProductId}</code>
                  <Button variant="ghost" size="sm" className="h-7 px-2" onClick={() => handleCopy(linkedProductId)}>
                    <Copy className="h-3.5 w-3.5" />
                  </Button>
                  <a href={`https://app.dodopayments.com/products/${linkedProductId}`} target="_blank" rel="noopener noreferrer">
                    <Button variant="ghost" size="sm" className="h-7 px-2"><ExternalLink className="h-3.5 w-3.5" /></Button>
                  </a>
                  <Button variant="outline" size="sm" className="h-7" onClick={handleVerify} disabled={verifying}>
                    {verifying ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <RefreshCw className="h-3.5 w-3.5 mr-1" />}Verify
                  </Button>
                  <Button variant="outline" size="sm" className="h-7" onClick={handleRecreate} disabled={syncing}>
                    {syncing ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}Recreate
                  </Button>
                  <Button variant="ghost" size="sm" className="h-7 text-destructive hover:text-destructive" onClick={handleUnlink}>
                    <XCircle className="h-3.5 w-3.5 mr-1" />Unlink
                  </Button>
                </div>

                {/* Verify result card */}
                {verifyResult && (
                  verifyResult.exists && productCard ? (
                    <div className={`rounded-lg border p-3 space-y-2 ${productCard.isActive ? "border-emerald-200 bg-emerald-50/60 dark:bg-emerald-950/20" : "border-amber-200 bg-amber-50/60 dark:bg-amber-950/20"}`}>
                      <div className="flex items-center gap-2">
                        <ShieldCheck className={`h-4 w-4 ${productCard.isActive ? "text-emerald-600" : "text-amber-500"}`} />
                        <span className="text-sm font-medium">{productCard.name}</span>
                        {productCard.isActive
                          ? <Badge className="text-[10px] bg-emerald-100 text-emerald-700 border-emerald-200 hover:bg-emerald-100">Active</Badge>
                          : <Badge variant="outline" className="text-[10px] text-amber-600 border-amber-300">Inactive</Badge>}
                      </div>
                      <div className="grid grid-cols-3 gap-2 text-xs">
                        <div className="bg-background/80 rounded px-2 py-1.5">
                          <p className="text-muted-foreground text-[10px] uppercase tracking-wide mb-0.5">Price</p>
                          <p className="font-medium">${productCard.priceUsd.toFixed(2)}</p>
                        </div>
                        <div className="bg-background/80 rounded px-2 py-1.5">
                          <p className="text-muted-foreground text-[10px] uppercase tracking-wide mb-0.5">Type</p>
                          <p className="font-medium">{productCard.priceType}</p>
                        </div>
                        <div className="bg-background/80 rounded px-2 py-1.5">
                          <p className="text-muted-foreground text-[10px] uppercase tracking-wide mb-0.5">PWYW</p>
                          {productCard.pwyw
                            ? <p className="font-medium text-emerald-600">✓ Enabled {productCard.pwywMin !== null ? `(min $${productCard.pwywMin})` : ""}</p>
                            : <p className="font-medium text-destructive">✗ Disabled</p>}
                        </div>
                      </div>
                      {!productCard.pwyw && (
                        <p className="text-[11px] text-amber-700 dark:text-amber-400 bg-amber-100/60 dark:bg-amber-900/20 rounded px-2 py-1.5">
                          ⚠ PWYW is off — users cannot pay a custom amount. Enable "Pay What You Want" for this product in the Dodo dashboard, then click Verify again.
                        </p>
                      )}
                    </div>
                  ) : (
                    <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-3 flex items-start gap-2">
                      <AlertCircle className="h-4 w-4 text-destructive mt-0.5 shrink-0" />
                      <div>
                        <p className="text-sm font-medium text-destructive">Product not found on Dodo</p>
                        <p className="text-xs text-muted-foreground mt-0.5">{verifyResult.error || "The linked product ID does not exist in your Dodo account. Click Recreate to create a new one."}</p>
                      </div>
                    </div>
                  )
                )}
              </div>
            ) : (
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="gap-1 text-xs text-amber-600 border-amber-300">
                    <AlertCircle className="h-3 w-3" />Not linked
                  </Badge>
                  <Button size="sm" onClick={handleSyncToDodo} disabled={syncing}>
                    {syncing ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : null}Create on Dodo
                  </Button>
                </div>

                {/* Manual link */}
                <div className="rounded-lg border border-dashed border-border p-3 space-y-2">
                  <p className="text-xs font-medium text-muted-foreground flex items-center gap-1.5">
                    <Link2 className="h-3.5 w-3.5" />Link an existing Dodo product
                  </p>
                  <div className="flex gap-2">
                    <Input
                      className="text-xs font-mono h-8"
                      placeholder="pdt_xxxxxxxxxxxxxxxxxxxx"
                      value={manualProductId}
                      onChange={(e) => setManualProductId(e.target.value)}
                    />
                    <Button size="sm" className="h-8 shrink-0" onClick={handleLinkManual} disabled={linking || !manualProductId.trim()}>
                      {linking ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <CheckCircle className="h-3.5 w-3.5 mr-1" />}Verify & Link
                    </Button>
                  </div>
                  <p className="text-[11px] text-muted-foreground">Paste the Product ID from your Dodo dashboard. The app will verify it exists before linking.</p>

                  {/* Verify result for manual link attempt */}
                  {verifyResult && (
                    verifyResult.exists && productCard ? (
                      <div className="rounded-lg border border-emerald-200 bg-emerald-50/60 dark:bg-emerald-950/20 p-3 space-y-2">
                        <div className="flex items-center gap-2">
                          <CheckCircle className="h-4 w-4 text-emerald-600" />
                          <span className="text-sm font-medium">{productCard.name}</span>
                          <Badge className="text-[10px] bg-emerald-100 text-emerald-700 border-emerald-200 hover:bg-emerald-100">Found</Badge>
                        </div>
                        <div className="grid grid-cols-3 gap-2 text-xs">
                          <div className="bg-background/80 rounded px-2 py-1.5">
                            <p className="text-muted-foreground text-[10px] uppercase tracking-wide mb-0.5">Price</p>
                            <p className="font-medium">${productCard.priceUsd.toFixed(2)}</p>
                          </div>
                          <div className="bg-background/80 rounded px-2 py-1.5">
                            <p className="text-muted-foreground text-[10px] uppercase tracking-wide mb-0.5">Type</p>
                            <p className="font-medium">{productCard.priceType}</p>
                          </div>
                          <div className="bg-background/80 rounded px-2 py-1.5">
                            <p className="text-muted-foreground text-[10px] uppercase tracking-wide mb-0.5">PWYW</p>
                            {productCard.pwyw
                              ? <p className="font-medium text-emerald-600">✓ On</p>
                              : <p className="font-medium text-destructive">✗ Off</p>}
                          </div>
                        </div>
                      </div>
                    ) : (
                      <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-3 flex items-start gap-2">
                        <AlertCircle className="h-4 w-4 text-destructive mt-0.5 shrink-0" />
                        <div>
                          <p className="text-sm font-medium text-destructive">Product not found</p>
                          <p className="text-xs text-muted-foreground mt-0.5">{verifyResult.error || "No product found with that ID in your Dodo account."}</p>
                        </div>
                      </div>
                    )
                  )}
                </div>
              </div>
            )}

            <p className="text-[11px] text-muted-foreground">
              This product handles all wallet top-ups. PWYW must be enabled in Dodo so users can pay any amount above the minimum.
            </p>
          </div>

        </CardContent>
      </Card>
    </div>
  );
};

export default WalletSettingsTab;

