import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import {
  ChevronDown, ChevronUp, Download, Trash2, Phone, Mail, MapPin,
  FileText, XCircle, CheckCircle2, Archive, Cpu, GraduationCap, FileCheck,
  Lightbulb
} from "lucide-react";
import { toast } from "sonner";
import type { Result } from "@/pages/Index";

interface CandidateRowProps {
  result: Result;
  index: number;
  isExpanded: boolean;
  isSelected: boolean;
  jobTitle?: string | null;
  onToggleRow: (id: string) => void;
  onToggleSelect: (resumeId: string) => void;
  onDownload: (filePath: string, filename: string) => void;
  onDelete: (resumeId: string, filePath: string | null) => void;
  onDismiss: (resumeId: string) => void;
  formatCandidateName: (filename: string) => string;
}

const getScoreColor = (score: number) => {
  if (score >= 70) return "bg-score-skills";
  if (score >= 40) return "bg-warning";
  return "bg-destructive";
};

const getScoreTextColor = (score: number) => {
  if (score >= 70) return "text-score-skills";
  if (score >= 40) return "text-warning";
  return "text-destructive";
};

const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

const getRankDisplay = (index: number) => {
  if (index < 3) {
    const colors = [
      "bg-score-overall text-white",
      "bg-muted-foreground/60 text-white",
      "bg-warning text-white",
    ];
    return (
      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
        {index + 1}
      </span>
    );
  }
  return (
    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
      {index + 1}
    </span>
  );
};

const CandidateRow = ({
  result: r,
  index,
  isExpanded,
  isSelected,
  jobTitle,
  onToggleRow,
  onToggleSelect,
  onDownload,
  onDelete,
  onDismiss,
  formatCandidateName,
}: CandidateRowProps) => {
  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;

  return (
    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
      <>
        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
          <TableCell onClick={(e) => e.stopPropagation()}>
            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
          </TableCell>
          <TableCell className="text-center">
            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
          </TableCell>
          <TableCell className="font-medium">
            <div className="flex flex-col">
              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
              {r.candidate_location && (
                <span className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
                  <MapPin className="h-3 w-3" /> {r.candidate_location}
                </span>
              )}
            </div>
          </TableCell>
          <TableCell>
            {r.pending ? (
              <Badge variant="outline" className="text-xs">Pending</Badge>
            ) : (
              <div className="flex items-center gap-2">
                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
                  <div
                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
                  />
                </div>
                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
                  {r.overall_score?.toFixed(0)}%
                </span>
              </div>
            )}
          </TableCell>
          <TableCell>
            <div className="flex flex-wrap items-center gap-1">
              {!r.pending && strength && (
                <Badge variant={strength.variant} className="text-[10px]">
                  {strength.label}
                </Badge>
              )}
              {!r.pending && r.scoring_version === "heuristic" && (
                <TooltipProvider delayDuration={300}>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
                        Quick
                      </span>
                    </TooltipTrigger>
                    <TooltipContent className="max-w-xs text-xs">
                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              )}
            </div>
          </TableCell>
          <TableCell>
            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
              <TooltipProvider delayDuration={300}>
                {/* Phone - always visible */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.candidate_phone ? (
                      <a
                        href={`tel:${r.candidate_phone}`}
                        onClick={(e) => {
                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
                            e.preventDefault();
                            navigator.clipboard.writeText(r.candidate_phone!);
                            toast.success("Phone number copied!");
                          }
                        }}
                      >
                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
                          <Phone className="h-3.5 w-3.5" />
                        </Button>
                      </a>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <Phone className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.candidate_phone || "No phone"}</TooltipContent>
                </Tooltip>

                {/* Email - always visible */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.candidate_email ? (
                      <a href={`mailto:${r.candidate_email}?subject=${encodeURIComponent(`Regarding Your Application – ${jobTitle || "Open Position"}`)}`}>
                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
                          <Mail className="h-3.5 w-3.5" />
                        </Button>
                      </a>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <Mail className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.candidate_email || "No email"}</TooltipContent>
                </Tooltip>

                {/* Document download */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.file_path ? (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
                        <FileText className="h-3.5 w-3.5" />
                      </Button>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <FileText className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
                </Tooltip>

                {/* Archive */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost" size="icon"
                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
                      onClick={() => onDismiss(r.resume_id)}
                    >
                      <Archive className="h-3.5 w-3.5" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Archive candidate</TooltipContent>
                </Tooltip>
              </TooltipProvider>

              {!r.pending && (
                <CollapsibleTrigger asChild>
                  <Button variant="ghost" size="icon" className="h-7 w-7">
                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
                  </Button>
                </CollapsibleTrigger>
              )}
            </div>
          </TableCell>
        </TableRow>

        {/* Expanded detail — 3-column + Strengths/Gaps */}
        {!r.pending && (
          <CollapsibleContent asChild>
            <TableRow className="bg-muted/30 hover:bg-muted/30">
              <TableCell colSpan={6} className="p-5">
                <div className="space-y-5">
                  {/* AI Summary */}
                  {(r.explanation_json?.summary || r.summary) && (
                    <p className="text-sm leading-relaxed text-foreground max-w-3xl">
                      {r.explanation_json?.summary || r.summary}
                    </p>
                  )}

                  {/* Heuristic scoring notice */}
                  {r.scoring_version === "heuristic" && (
                    <div className="flex items-center gap-2">
                      <Badge variant="outline" className="text-[10px] text-muted-foreground">
                        Quick Match (top 20 scored with AI)
                      </Badge>
                    </div>
                  )}

                  {/* 3-Column Layout: Skills | Education | JD Match */}
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    {/* Column 1: Skills Breakdown */}
                    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
                      <div className="flex items-center gap-2 mb-1">
                        <div className="w-6 h-6 rounded bg-score-skills/10 flex items-center justify-center">
                          <Cpu className="h-3.5 w-3.5 text-score-skills" />
                        </div>
                        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Skills</h4>
                      </div>
                      {r.category_scores_json && typeof r.category_scores_json === "object" ? (
                        <div className="space-y-2">
                          {Object.entries(r.category_scores_json as Record<string, { score: number; notes?: string }>).map(([skill, data]) => (
                            <div key={skill} className="space-y-0.5">
                              <div className="flex items-center justify-between text-xs">
                                <span className="text-muted-foreground capitalize">{skill.replace(/_/g, " ")}</span>
                                <span className="font-semibold tabular-nums">{data.score}%</span>
                              </div>
                              <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                                <div className="h-full rounded-full bg-score-skills transition-all" style={{ width: `${Math.min(data.score, 100)}%` }} />
                              </div>
                            </div>
                          ))}
                        </div>
                      ) : null}
                      {/* Missing skills */}
                      {r.missing_skills && r.missing_skills.length > 0 && (
                        <div className="pt-1 space-y-1">
                          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Missing</span>
                          <div className="flex flex-wrap gap-1">
                            {r.missing_skills.map((skill, i) => (
                              <span key={i} className="inline-flex items-center gap-0.5 text-[10px] px-1.5 py-0.5 rounded bg-destructive/10 text-destructive">
                                <XCircle className="h-2.5 w-2.5" /> {skill}
                              </span>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>

                    {/* Column 2: Education Match */}
                    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
                      <div className="flex items-center gap-2 mb-1">
                        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
                          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
                        </div>
                        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Confidence</h4>
                        <span className="ml-auto text-sm font-bold text-score-education tabular-nums">{(r.confidence ?? 0).toFixed(0)}%</span>
                      </div>
                      <div className="h-1.5 rounded-full bg-secondary overflow-hidden mb-2">
                        <div className="h-full rounded-full bg-score-education transition-all" style={{ width: `${Math.min(r.confidence ?? 0, 100)}%` }} />
                      </div>
                      {(r.confidence ?? 0) >= 70 ? (
                        <Badge variant="success" className="text-[10px]">High Confidence</Badge>
                      ) : (r.confidence ?? 0) >= 40 ? (
                        <Badge variant="warning" className="text-[10px]">Medium Confidence</Badge>
                      ) : (
                        <Badge variant="destructive" className="text-[10px]">Low Confidence</Badge>
                      )}
                      {r.explanation_json?.key_tradeoffs && (
                        <p className="text-xs text-muted-foreground leading-relaxed mt-2">
                          {r.explanation_json.key_tradeoffs}
                        </p>
                      )}
                    </div>

                    {/* Column 3: JD Requirements Match */}
                    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
                      <div className="flex items-center gap-2 mb-1">
                        <div className="w-6 h-6 rounded bg-score-jd/10 flex items-center justify-center">
                          <FileCheck className="h-3.5 w-3.5 text-score-jd" />
                        </div>
                        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">JD Match</h4>
                      </div>
                      {/* Matched requirements */}
                      {r.matched_must_haves && (r.matched_must_haves as string[]).length > 0 && (
                        <div className="space-y-1">
                          {(r.matched_must_haves as string[]).map((item, i) => (
                            <div key={i} className="flex items-start gap-1.5 text-xs">
                              <CheckCircle2 className="h-3.5 w-3.5 text-success shrink-0 mt-0.5" />
                              <span className="text-foreground">{item}</span>
                            </div>
                          ))}
                        </div>
                      )}
                      {/* Missing requirements */}
                      {r.missing_must_haves && (r.missing_must_haves as string[]).length > 0 && (
                        <div className="space-y-1 pt-1">
                          {(r.missing_must_haves as string[]).map((item, i) => (
                            <div key={i} className="flex items-start gap-1.5 text-xs">
                              <XCircle className="h-3.5 w-3.5 text-destructive shrink-0 mt-0.5" />
                              <span className="text-muted-foreground">{item}</span>
                            </div>
                          ))}
                        </div>
                      )}
                      {/* AI suggestion */}
                      {r.explanation_json?.why_ranked_here && (
                        <div className="mt-2 p-2 rounded bg-score-overall/5 border border-score-overall/20">
                          <div className="flex items-start gap-1.5">
                            <Lightbulb className="h-3.5 w-3.5 text-score-overall shrink-0 mt-0.5" />
                            <p className="text-[11px] text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Two-column Strengths & Gaps */}
                  {((r.strengths_json || r.matched_must_haves || []).length > 0 || (r.gaps_json || r.missing_skills || []).length > 0) && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {/* Strengths */}
                      <div className="space-y-2">
                        <h5 className="text-xs font-semibold text-success uppercase tracking-wide flex items-center gap-1">
                          <CheckCircle2 className="h-3.5 w-3.5" /> Strengths
                        </h5>
                        <div className="space-y-1.5">
                          {(r.strengths_json || r.matched_must_haves || []).slice(0, 6).map((s: string, i: number) => (
                            <div key={i} className="flex items-center gap-2 text-xs px-2.5 py-1.5 rounded-md bg-success/5 border border-success/15 text-foreground">
                              <CheckCircle2 className="h-3 w-3 text-success shrink-0" />
                              {s}
                            </div>
                          ))}
                        </div>
                      </div>
                      {/* Gaps */}
                      <div className="space-y-2">
                        <h5 className="text-xs font-semibold text-destructive uppercase tracking-wide flex items-center gap-1">
                          <XCircle className="h-3.5 w-3.5" /> Gaps
                        </h5>
                        <div className="space-y-1.5">
                          {(r.gaps_json || r.missing_must_haves || r.missing_skills || []).slice(0, 6).map((g: string, i: number) => (
                            <div key={i} className="flex items-center gap-2 text-xs px-2.5 py-1.5 rounded-md bg-destructive/5 border border-destructive/15 text-foreground">
                              <XCircle className="h-3 w-3 text-destructive shrink-0" />
                              {g}
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Interview Questions */}
                  {r.interview_questions && Array.isArray(r.interview_questions) && r.interview_questions.length > 0 && (
                    <div>
                      <p className="text-xs font-medium text-muted-foreground mb-2">Interview Questions</p>
                      <ol className="text-sm list-decimal list-inside space-y-1 text-muted-foreground">
                        {r.interview_questions.map((q: string, i: number) => <li key={i}>{q}</li>)}
                      </ol>
                    </div>
                  )}
                </div>
              </TableCell>
            </TableRow>
          </CollapsibleContent>
        )}
      </>
    </Collapsible>
  );
};

