                      <XCircle className="h-3 w-3 text-destructive shrink-0 mt-0.5" />
                      <span className="leading-tight">{item}</span>
                    </div>
                    <span className="text-[10px] text-destructive font-semibold shrink-0">Gap</span>
                  </div>
                ))}
                {!(r.matched_must_haves?.length) && !(r.missing_must_haves?.length) && (
                  <p className="text-[11px] text-muted-foreground italic">No JD requirements matched</p>
                )}
              </div>
            </div>

          </div>

          {/* Interview Questions */}
          {r.interview_questions && Array.isArray(r.interview_questions) && r.interview_questions.length > 0 && (
            <div>
              <p className="text-xs font-medium text-muted-foreground mb-2">Interview Questions</p>
              <ol className="text-sm list-decimal list-inside space-y-1 text-muted-foreground">
                {r.interview_questions.map((q: string, i: number) => <li key={i}>{q}</li>)}
              </ol>
            </div>
          )}

        </div>
      </TableCell>
    </TableRow>
  </CollapsibleContent>
)}

